--   
--   El uso de la marca debe hacerse de acuerdo con la ley especial respectiva, y
--   durante el plazo de eficacia del registro que dicha ley determine,', '672', 'Codigo de Comercio (Decreto 73-50)', '{"norm_id":"mayalex_normativos:codigo_comercio_bch_d73_50","instrumento":"Código de Comercio (Decreto 73-50)","rol":"PRIMARY","hash_texto_sha256":"1347eb6af7922e54b0a1f7c4afb2fccde36d29fb02f2f0699452afc04567217c","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[]}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'codigo', false),
