--   
--   Todo comerciante puede añadir su propia marca a la del productor, pero sin
--   suprimir, alterar u ocultar la de éste.', '673', 'Codigo de Comercio (Decreto 73-50)', '{"norm_id":"mayalex_normativos:codigo_comercio_bch_d73_50","instrumento":"Código de Comercio (Decreto 73-50)","rol":"PRIMARY","hash_texto_sha256":"e10a1e602ea17e5101564f726bcec59321e928ea546c531c6b3ce4b4491d2492","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[]}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'codigo', false),
