--   
--                             De las patentes de invención', '677', 'Codigo de Comercio (Decreto 73-50)', '{"norm_id":"mayalex_normativos:codigo_comercio_bch_d73_50","instrumento":"Código de Comercio (Decreto 73-50)","rol":"PRIMARY","hash_texto_sha256":"471d65af7330b9a674a635ce84f91f53b0b9ecbc89ef7b75703d678d3fb67ad8","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[]}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'codigo', false),
