--   aquélla se determine.', '678', 'Codigo de Comercio (Decreto 73-50)', '{"norm_id":"mayalex_normativos:codigo_comercio_bch_d73_50","instrumento":"Código de Comercio (Decreto 73-50)","rol":"PRIMARY","hash_texto_sha256":"7cc50bee96ad741455b048ca8e11acb9dbca8f57b812664adfdaf4537c5f66ed","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[]}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'codigo', false),
